/**
 * Reference implementation of the contact-form POST endpoint that
 * `scripts/contact.js` is wired to call.
 * THIS FILE IS NOT SERVED BY THE STATIC HOST — it is a starting point for a
 * custom backend. Treat it as documentation of the request/response shape
 * that the frontend expects.
 *
 * Wire it into a runtime such as Vercel, Netlify Functions, Cloudflare Workers,
 * or an Express route. The example below is runnable as a standalone Node script
 * and exports a handler for embedding in a server.
 *
 * Expected request:
 *   POST /api/contact
 *   Content-Type: application/json
 *   {
 *     "name":    "Ada Lovelace",
 *     "email":   "ada@example.com",
 *     "message": "I'd like to learn more about Lumen."
 *     // Optional: "website": "https://example.com" (honeypot — drop if present)
 *   }
 *
 * Expected response (success):
 *   200 OK
 *   { "ok": true, "id": "cklq2..." }
 *   // (or any object — the client only inspects `ok` and `id`)
 *
 * Expected response (error):
 *   4xx / 5xx with JSON body { "ok": false, "error": "<message>" }
 *
 * Environment variables (optional):
 *   PORT               — TCP port to listen on when run standalone (default 8787).
 *   LUMEN_CONTACT_TO   — Destination inbox for forwarded inquiries (default
 *                         "hello@lumen.example").
 *   LUMEN_RATE_LIMIT   — Max submissions per IP per hour (default 5).
 *
 * Security basics:
 *   - Honeypot field "website" must be empty; non-empty requests are silently
 *     dropped.
 *     - Email is validated against a conservative regex and length-capped.
 *     - Message length is capped (default 4000 chars).
 *     - A simple in-memory rate limit per IP is enforced.
 *     - Responses always set `Content-Type: application/json`.
 *   - The handler exports `handle` so it can be mounted by Vercel, Netlify,
 *     Cloudflare Workers, or any Node-based server.
 *   - CORS is permissive (`Access-Control-Allow-Origin: *`) because the site
 *     itself is static; tighten this for production.
 *   - No third-party dependencies.
 *
 * To run standalone:
 *   node server/contact-handler.example.js
 */

'use strict';

const PORT = Number(process.env.PORT) || 8787;
const LUMEN_CONTACT_TO = process.env.LUMEN_CONTACT_TO || 'hello@lumen.example';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const MAX_NAME = 120;
const MAX_EMAIL = 254;
const MAX_MESSAGE = 4000;
const RATE_WINDOW_MS = 60 * 60 * 1000; // 1 hour
const RATE_MAX = Number(process.env.LUMEN_RATE_LIMIT) || 5;

/**
 * Build a JSON response with the right headers.
 */
function jsonResponse(status, body) {
  return {
    status,
    headers: {
      'Content-Type': 'application/json',
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Headers': 'Content-Type',
      'Access-Control-Allow-Methods': 'POST, OPTIONS',
    },
    body: JSON.stringify(body),
  };
}

/**
 * Simple in-memory per-IP rate limiter.
 */
const rateBuckets = new Map();
function checkRate(ip) {
  const now = Date.now();
  const bucket = rateBuckets.get(ip) || [];
  const fresh = bucket.filter((ts) => now - ts < RATE_WINDOW_MS);
  if (fresh.length >= RATE_MAX) {
    return false;
  }
  fresh.push(now);
  rateBuckets.set(ip, fresh);
  return true;
}

/**
 * Extract the caller's IP from common proxy headers, falling back to a
 * placeholder. The host (Vercel/Netlify/Cloudflare) populates these.
 *
 * @param {object} headers
 * @returns {string}
 */
function getClientIp(headers) {
  const xff = headers['x-forwarded-for'] || headers['X-Forwarded-For'];
  if (typeof xff === 'string' && xff.length > 0) {
    return xff.split(',')[0].trim();
  }
  return '0.0.0.0';
}

/**
 * Main request handler — platform agnostic.
 *
 * @param {object} request
 * @param {object} request.method
 * @param {object} request.headers
 * @param {string|object} request.body  JSON string or already-parsed object
 * @returns {{status:number, headers:object, body:string}}
 */
function handle(request) {
  const method = (request && request.method) || 'GET';

  if (method === 'OPTIONS') {
    return jsonResponse(204, { ok: true });
  }

  if (method !== 'POST') {
    return jsonResponse(405, { ok: false, error: 'Method not allowed' });
  }

  let payload;
  if (typeof request.body === 'string') {
    try {
      payload = JSON.parse(request.body);
    } catch (e) {
      return jsonResponse(400, { ok: false, error: 'Invalid JSON body' });
    }
  } else {
    payload = request.body || {};
  }

  const name = typeof payload.name === 'string' ? payload.name.trim() : '';
  const email = typeof payload.email === 'string' ? payload.email.trim() : '';
  const message = typeof payload.message === 'string' ? payload.message.trim() : '';
  const website = typeof payload.website === 'string' ? payload.website.trim() : '';

  // Honeypot — silently accept and drop bot submissions.
  if (website.length > 0) {
    return jsonResponse(200, { ok: true, id: 'dropped' });
  }

  if (!name || name.length > MAX_NAME) {
    return jsonResponse(400, { ok: false, error: 'Name is required (max ' + MAX_NAME + ' chars).' });
  }
  if (!email || email.length > MAX_EMAIL || !EMAIL_RE.test(email)) {
    return jsonResponse(400, { ok: false, error: 'A valid email is required.' });
  }
  if (!message || message.length > MAX_MESSAGE) {
    return jsonResponse(400, { ok: false, error: 'Message is required (max ' + MAX_MESSAGE + ' chars).' });
  }

  const ip = getClientIp(request.headers || {});
  if (!checkRate(ip)) {
    return jsonResponse(429, { ok: false, error: 'Too many requests. Try again later.' });
